### 1. The Core Strike: Production-Ready Baseline (Java 21)

Forget toy `Hello World` scripts. A proper Java program requires clear separation of concerns, immutability by default, robust error handling, and thread safety.

Here is a resilient, self-contained batch processor engine—designed to prevent the exact **high-payload batch timeouts** we've fought in the past.

```java
package com.mugiwara.engine;

import java.time.Instant;
import java.util.List;
import java.util.Objects;
import java.util.concurrent.*;
import java.util.logging.Level;
import java.util.logging.Logger;

/**
 * High-Throughput Batch Processing Core.
 * Built for Java 21 LTS using Virtual Threads and Immutable Records.
 */
public final class BatchEngine {

    private static final Logger LOGGER = Logger.getLogger(BatchEngine.class.getName());

    // 1. Immutable Data Model (Java Record)
    public record TaskPayload(String id, String data, Instant createdAt) {
        public TaskPayload {
            Objects.requireNonNull(id, "Task ID cannot be null");
            Objects.requireNonNull(data, "Payload data cannot be null");
            if (createdAt == null) createdAt = Instant.now();
        }
    }

    public record ProcessingResult(String taskId, boolean success, String message, long executionTimeMs) {}

    // 2. Service Boundary Interface
    public interface TaskProcessor {
        ProcessingResult process(TaskPayload payload);
    }

    // 3. Resilient Processor Implementation
    public static class ResilientTaskProcessor implements TaskProcessor {
        @Override
        public ProcessingResult process(TaskPayload payload) {
            long start = System.currentTimeMillis();
            try {
                // Simulating payload transformation/DB persistence
                if (payload.data().isBlank()) {
                    throw new IllegalArgumentException("Payload cannot be blank");
                }

                // Emulate light work
                Thread.sleep(50); 

                long duration = System.currentTimeMillis() - start;
                return new ProcessingResult(payload.id(), true, "EXECUTED_CLEANLY", duration);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                return new ProcessingResult(payload.id(), false, "INTERRUPTED", System.currentTimeMillis() - start);
            } catch (Exception e) {
                return new ProcessingResult(payload.id(), false, "FAILED: " + e.getMessage(), System.currentTimeMillis() - start);
            }
        }
    }

    // 4. Concurrency Orchestrator using Virtual Threads (Project Loom)
    public static class BatchOrchestrator {
        private final TaskProcessor processor;

        public BatchOrchestrator(TaskProcessor processor) {
            this.processor = processor;
        }

        public List<ProcessingResult> executeBatch(List<TaskPayload> payloads, long timeoutSeconds) {
            // Virtual thread executor cuts down I/O bottleneck without heavy OS thread overhead
            try (ExecutorService executor = Executors.newVirtualThreadPerTaskExecutor()) {
                List<Callable<ProcessingResult>> tasks = payloads.stream()
                        .map(payload -> (Callable<ProcessingResult>) () -> processor.process(payload))
                        .toList();

                List<Future<ProcessingResult>> futures = executor.invokeAll(
                        tasks, 
                        timeoutSeconds, 
                        TimeUnit.SECONDS
                );

                return futures.stream()
                        .map(future -> {
                            try {
                                if (future.isCancelled()) {
                                    return new ProcessingResult("UNKNOWN", false, "TIMEOUT_BREACHED", 0);
                                }
                                return future.get();
                            } catch (Exception e) {
                                return new ProcessingResult("UNKNOWN", false, "EXECUTION_EXCEPTION: " + e.getMessage(), 0);
                            }
                        })
                        .toList();
            } catch (InterruptedException e) {
                LOGGER.log(Level.SEVERE, "Batch execution interrupted", e);
                Thread.currentThread().interrupt();
                return List.of();
            }
        }
    }

    // 5. Execution Entry Point
    public static void main(String[] args) {
        LOGGER.info("Santoryu Engine Initializing...");

        List<TaskPayload> incomingBatch = List.of(
                new TaskPayload("T-101", "Payload Alpha", Instant.now()),
                new TaskPayload("T-102", "Payload Beta", Instant.now()),
                new TaskPayload("T-103", "", Instant.now()), // Edge-case test (invalid)
                new TaskPayload("T-104", "Payload Gamma", Instant.now())
        );

        TaskProcessor processor = new ResilientTaskProcessor();
        BatchOrchestrator orchestrator = new BatchOrchestrator(processor);

        long startTime = System.currentTimeMillis();
        List<ProcessingResult> results = orchestrator.executeBatch(incomingBatch, 5);
        long totalElapsed = System.currentTimeMillis() - startTime;

        System.out.println("================ RESULTS ================");
        results.forEach(r -> System.out.printf("[%s] ID: %s | Message: %s (%dms)%n",
                r.success() ? "PASS" : "FAIL", r.taskId(), r.message(), r.executionTimeMs()));
        System.out.printf("Batch processed in %d ms%n", totalElapsed);
    }
}
```

